operation.add:
// [cart_lifetime] Persistent guest cart. Contract: see README.
const CART_LIFETIME_DAYS = 30;          // guest rows and cookie, counted from last activity
const CART_LIFETIME_API_HOURS = 1;      // API (admin order editor) rows, stock value
const CART_LIFETIME_TOUCH_HOURS = 24;   // date_added is refreshed at most this often
const CART_LIFETIME_GC_DIVISOR = 1000;  // GC runs on ~1/N requests; 0 = off (run it from cron)
const CART_LIFETIME_COOKIE = 'cart_lifetime';
const CART_LIFETIME_LEGACY_COOKIE = 'cart_hash';

private $cart_lifetime_key = null;
private $cart_lifetime_pending = false;

// The stock queries use this instead of the session ID. A guest cart is keyed by a
// token that does not change when the session does, so concurrent requests that
// arrive without a session all resolve to the same rows and nothing is moved.
private function cart_lifetime_key() {
	if ($this->cart_lifetime_key === null) {
		$this->cart_lifetime_resolve();
	}

	return $this->cart_lifetime_key;
}

// For code outside this class that queries oc_cart itself (stock PayPal models).
public function getLifetimeKey() {
	return $this->cart_lifetime_key();
}

private function cart_lifetime_resolve() {
	$session_id = $this->session->getId();

	if (isset($this->session->data['api_id'])) {
		$this->cart_lifetime_key = $session_id;

		return;
	}

	$stored = isset($this->session->data['cart_lifetime_key']) ? (string)$this->session->data['cart_lifetime_key'] : '';
	// is_string(): name[]=x arrives as an array.
	$cookie = isset($_COOKIE[self::CART_LIFETIME_COOKIE]) && is_string($_COOKIE[self::CART_LIFETIME_COOKIE]) ? $_COOKIE[self::CART_LIFETIME_COOKIE] : '';
	$legacy = isset($_COOKIE[self::CART_LIFETIME_LEGACY_COOKIE]) && is_string($_COOKIE[self::CART_LIFETIME_LEGACY_COOKIE]) ? $_COOKIE[self::CART_LIFETIME_LEGACY_COOKIE] : '';
	$restored = false;

	if (preg_match('/^[a-f0-9]{32}$/D', $cookie)) {
		$key = $cookie;
		$restored = ($key !== $stored);
	} elseif (preg_match('/^[a-zA-Z0-9,\-]{22,32}$/D', $legacy)) {
		// Up to v1.11 the cookie held a raw session ID and the rows are still keyed by it.
		$key = $this->cart_lifetime_derive($legacy);
		$restored = $this->cart_lifetime_migrate($legacy, $key);

		if ($restored) {
			$this->cart_lifetime_setcookie(self::CART_LIFETIME_LEGACY_COOKIE, '', time() - 3600);
		}
	} elseif (preg_match('/^[a-f0-9]{32}$/D', $stored)) {
		$key = $stored;
	} else {
		// Derived rather than random, so parallel first requests of one session agree.
		// The migration picks up rows written under the session ID before installation.
		$key = $this->cart_lifetime_derive($session_id);
		$this->cart_lifetime_migrate($session_id, $key);
	}

	$this->cart_lifetime_key = $key;

	// A failed migration is retried on the next request: do not record the key yet.
	if (!$this->cart_lifetime_pending) {
		$this->session->data['cart_lifetime_key'] = $key;
	}

	if ($restored) {
		$this->cart_lifetime_touch();
	}
}

// One-way, so the cookie never discloses a session ID.
private function cart_lifetime_derive($session_id) {
	return substr(hash('sha256', 'cart_lifetime:' . $session_id), 0, 32);
}

// Moves rows verbatim and never deletes, so no quantity can be lost. The target is
// derived from the source, so concurrent requests move to the same place and the
// later ones simply match nothing.
private function cart_lifetime_migrate($from, $to) {
	try {
		$found = $this->db->query("SELECT cart_id FROM " . DB_PREFIX . "cart WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $this->db->escape($from) . "' LIMIT 1");

		if ($found->num_rows) {
			$this->db->query("UPDATE " . DB_PREFIX . "cart SET session_id = '" . $this->db->escape($to) . "', date_added = NOW() WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $this->db->escape($from) . "'");
		}

		return true;
	} catch (\Exception $e) {
		$this->cart_lifetime_pending = true;
		$this->cart_lifetime_log('migrate', $e);

		return false;
	}
}

// Sliding lifetime: the cookie and date_added are extended together. The cookie is
// rewritten on every call, so it always outlives the rows it points to.
private function cart_lifetime_touch() {
	if (isset($this->session->data['api_id']) || $this->customer->isLogged()) {
		return;
	}

	$key = $this->cart_lifetime_key();

	// While a migration is pending the old cookie is the only pointer to the rows.
	if (!$this->cart_lifetime_pending) {
		$this->cart_lifetime_setcookie(self::CART_LIFETIME_COOKIE, $key, time() + 86400 * self::CART_LIFETIME_DAYS);
	}

	try {
		$this->db->query("UPDATE " . DB_PREFIX . "cart SET date_added = NOW() WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $this->db->escape($key) . "' AND date_added < DATE_SUB(NOW(), INTERVAL " . (int)self::CART_LIFETIME_TOUCH_HOURS . " HOUR)");
	} catch (\Exception $e) {
		$this->cart_lifetime_log('touch', $e);
	}
}

// Housekeeping is best effort: a deadlock here must not fail the page. A real outage
// still surfaces through the stock queries that follow.
private function cart_lifetime_init() {
	$this->cart_lifetime_key();

	if (self::CART_LIFETIME_GC_DIVISOR > 0 && mt_rand(1, self::CART_LIFETIME_GC_DIVISOR) === 1) {
		try {
			$this->db->query("DELETE FROM " . DB_PREFIX . "cart WHERE api_id > '0' AND date_added < DATE_SUB(NOW(), INTERVAL " . (int)self::CART_LIFETIME_API_HOURS . " HOUR) LIMIT 200");
			$this->db->query("DELETE FROM " . DB_PREFIX . "cart WHERE api_id = '0' AND customer_id = '0' AND date_added < DATE_SUB(NOW(), INTERVAL " . (int)self::CART_LIFETIME_DAYS . " DAY) LIMIT 500");
		} catch (\Exception $e) {
			$this->cart_lifetime_log('gc', $e);
		}
	}
}

private function cart_lifetime_setcookie($name, $value, $expires) {
	if (headers_sent()) {
		return false;
	}

	// $_SERVER['HTTPS'] is already normalised by system/startup.php, proxy headers included.
	$secure = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
	$path = ini_get('session.cookie_path') ? ini_get('session.cookie_path') : '/';
	$domain = ini_get('session.cookie_domain') ? ini_get('session.cookie_domain') : '';

	if (PHP_VERSION_ID >= 70300) {
		return setcookie($name, $value, array(
			'expires'  => $expires,
			'path'     => $path,
			'domain'   => $domain,
			'secure'   => $secure,
			'httponly' => true,
			'samesite' => 'Lax'
		));
	}

	return setcookie($name, $value, $expires, $path, $domain, $secure, true);
}

// Never log the message: the stock adapter appends the full SQL, cart keys included.
private function cart_lifetime_log($operation, \Exception $e) {
	$code = $e->getCode();

	if (!$code && preg_match('/Error No: (\d+)/', $e->getMessage(), $match)) {
		$code = $match[1];
	}

	error_log('cart_lifetime: ' . $operation . ' failed (' . get_class($e) . ', code ' . (int)$code . ')');
}
